public class ArraySizeDetector extends Detector implements XmlScanner {
    private static final String TAG_STRING_ARRAY = "string-array";
    private static final String TAG_INTEGER_ARRAY = "integer-array";
    private static final String TAG_ARRAY = "array";
    private static final String TAG_ITEM = "item";
    private static final String ATTR_NAME = "name";

    private Map<String, Map<String, ArrayInfo>> mArrays = new HashMap<>();

    public static final Issue INCONSISTENT_ARRAYS = Issue.create(
            "InconsistentArrays",
            "Inconsistent array sizes",
            "When an array is translated ...",
            Category.I18N,
            3,
            Severity.WARNING,
            new Implementation(ArraySizeDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        mArrays.clear();
    }

    @Override
    @NonNull
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_STRING_ARRAY, TAG_INTEGER_ARRAY, TAG_ARRAY);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        ResourceFolderType folderType = ResourceFolderType.getFolderType(context.file.getParentFile().getName());
        if (folderType != ResourceFolderType.VALUES) {
            return;
        }
        String name = element.getAttribute(ATTR_NAME);
        if (name.isEmpty()) {
            return;
        }
        int count = 0;
        NodeList children = element.getChildNodes();
        for (int i = 0, n = children.getLength(); i < n; i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE && TAG_ITEM.equals(child.getNodeName())) {
                count++;
            }
        }
        String config = context.file.getParentFile().getName();
        String key = context.getProject().getName() + "/" + name;
        Map<String, ArrayInfo> configs = mArrays.get(key);
        if (configs == null) {
            configs = new HashMap<>();
            mArrays.put(key, configs);
        }
        if (!configs.containsKey(config)) {
            configs.put(config, new ArrayInfo(config, count, context.getLocation(element)));
        }
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        for (Map.Entry<String, Map<String, ArrayInfo>> entry : mArrays.entrySet()) {
            Map<String, ArrayInfo> configs = entry.getValue();
            if (configs.size() < 2) {
                continue;
            }
            int expected = -1;
            boolean consistent = true;
            for (ArrayInfo info : configs.values()) {
                if (expected == -1) {
                    expected = info.count;
                } else if (info.count != expected) {
                    consistent = false;
                    break;
                }
            }
            if (consistent) {
                continue;
            }
            String arrayName = entry.getKey().substring(entry.getKey().indexOf('/') + 1);
            for (ArrayInfo info : configs.values()) {
                String message = String.format(
                    "Array \"%s\" has %d items in %s",
                    arrayName, info.count, info.config);
                context.report(INCONSISTENT_ARRAYS, info.location, message);
            }
        }
    }

    private static class ArrayInfo {
        final String config;
        final int count;
        final Location location;
        ...
    }
}
